import {compare,parseMidi,validateEvents,demoEvents,reportText,noteName,VERSION} from './core.js';
const $=id=>document.getElementById(id), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state={reference:null,learner:null,result:null,demo:true}, audioContext, sources=[], playing=false, stopTimer, recorder,recordingSide, mediaStream, selectedId=null, vision=null, busy=false;
const toast=message=>{$('toast').textContent=message;$('toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').classList.remove('visible'),5000);};
function getHistory(){try{return JSON.parse(localStorage.getItem('bh-history-v1')||'[]');}catch{return [];}}
function persistHistory(h){try{localStorage.setItem('bh-history-v1',JSON.stringify(h.slice(0,30)));$('sessionCount').textContent=Math.min(h.length,30);}catch{toast('Browser storage is unavailable or full. Download your report instead.');}}
function download(data,name,type='text/plain'){const u=URL.createObjectURL(new Blob([data],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function audio(){return audioContext??=new (window.AudioContext||window.webkitAudioContext)();}
function stop(){sources.forEach(n=>{try{n.stop();}catch{}});sources=[];['reference','learner'].forEach(s=>$(s+'Video').pause());clearTimeout(stopTimer);playing=false;$('playBoth').textContent='▶';}
function cleanSide(s){if(state[s]?.url)URL.revokeObjectURL(state[s].url);const v=$(s+'Video');v.pause();v.removeAttribute('src');v.load();v.classList.add('hidden');$(s+'Canvas').classList.remove('hidden');}
function draw(s){const canvas=$(s+'Canvas'),ctx=canvas.getContext('2d');canvas.width=1000;canvas.height=480;ctx.clearRect(0,0,1000,480);if(state[s]?.url&&state[s]?.mediaType==='video')return;const notes=state[s]?.events||[];ctx.strokeStyle='#cddbc11c';ctx.lineWidth=1;for(let x=45;x<980;x+=68){ctx.beginPath();ctx.moveTo(x,60);ctx.lineTo(x,350);ctx.stroke();}for(let y=80;y<330;y+=38){ctx.beginPath();ctx.moveTo(30,y);ctx.lineTo(970,y);ctx.stroke();}
 if(!notes.length){ctx.fillStyle='#c8d5bf';ctx.font='24px system-ui';ctx.fillText(state[s]?'Recording ready to review':'A little knowledge begins here.',60,190);ctx.fillStyle='#90a78f';ctx.font='18px system-ui';ctx.fillText('Add a recording, MIDI phrase, or event file',60,230);return;}
 const end=Math.max(...notes.map(e=>e.end)),low=Math.min(...notes.map(e=>e.pitch))-2,high=Math.max(...notes.map(e=>e.pitch))+2;
 for(const e of notes){const x=45+e.start/end*890,y=310-(e.pitch-low)/(high-low)*210,w=Math.max(6,(e.end-e.start)/end*890);ctx.fillStyle=s==='reference'?'#adc4a0':'#d8b78f';ctx.globalAlpha=.8;ctx.beginPath();ctx.roundRect(x,y,w,14,5);ctx.fill();ctx.globalAlpha=1;ctx.fillStyle='#e1e7da';ctx.font='16px system-ui';ctx.fillText(noteName(e.pitch),x,y-10);}
 ctx.fillStyle='#bbceb244';ctx.font='11px system-ui';ctx.fillText('NOTE EVENT TIMELINE · ORIGINAL TIMESTAMPS',46,50);}
function updateSide(s){const x=state[s];$(s+'Name').textContent=x?.name||'No recording added';$(s+'Meta').textContent=x?`${x.events?.length||0} note events · ${x.sourceLabel}`:'MIDI, audio, video, or event JSON';$(s+'Duration').textContent=x?`${x.duration.toFixed(1)} s`:'—';draw(s);}
function render(){const r=state.result;const visible=r?.findings.filter(f=>f.review!=='dismissed')||[];$('findingCount').textContent=visible.length;$('resultStatus').textContent=r?(r.score===null?'REVIEW THE EVIDENCE':'COMPARISON READY'):'READY WHEN YOU ARE';$('score').innerHTML=`${r?.score??'—'}<small>/ 100</small>`;$('scoreDescription').textContent=!r?'Add your reference and attempt to get started.':r.score===null?'Score withheld. These observations need review.':'Notes and eligible rhythm only. Tone and technique excluded.';
 $('dimensions').innerHTML=['notes','rhythm','tone','technique'].map(k=>`<div class="dimension"><span>${({notes:'Note accuracy',rhythm:'Timing',tone:'Tone',technique:'Technique'})[k]}</span><span class="bar"><i style="width:${r?.dimensions[k]??0}%"></i></span><b>${r?.dimensions[k]??'—'}</b></div>`).join('');
 $('findings').innerHTML=!r?'<div class="empty"><h3>Your practice starts here.</h3><p>Add an expert recording and your attempt, then compare.</p></div>':visible.length?visible.map(f=>`<article class="finding ${selectedId===f.id?'selected':''}" data-finding="${esc(f.id)}"><div class="finding-main"><span class="finding-icon">${f.category==='Timing'?'◷':f.category==='Observation'?'◎':'♫'}</span><div><h4>${esc(f.category)}${f.delta?` · ${Math.round(Math.abs(f.delta)*1000)} ms`:''}</h4><p>${esc(f.observation)}</p></div><span class="finding-status ${f.status!=='confirmed'?'possible':''}">${esc(f.status.toUpperCase())}</span></div><div class="finding-actions"><button class="timestamp" data-replay="${esc(f.id)}">▶ ${f.learner?f.learner[0].toFixed(2)+' s':'Reference '+f.reference?.[0].toFixed(2)+' s'} ↗</button><button class="review" data-review="accept" data-id="${esc(f.id)}">${f.review==='accepted'?'✓ Reviewed':'Mark reviewed'}</button><button class="review" data-review="dismiss" data-id="${esc(f.id)}">Dismiss</button></div><div class="practice-tip">↳ ${esc(f.action)}</div></article>`).join(''):`<div class="empty"><h3>${r.referenceCount?'No significant differences detected.':'Ready for an expert eye.'}</h3><p>${r.referenceCount?'In the dimensions assessed. Technique and tone still need human review.':'Play the recordings and add a timestamped observation.'}</p></div>`;
 if(r)$('findings').insertAdjacentHTML('beforeend','<button id="addObservation" class="button text full">＋ Add an instructor observation</button>');$('unassessed').innerHTML=`<span>ⓘ</span><span>${esc(r?.limitations.join(' ')||'Only observable differences will appear here. No recording is uploaded to a cloud server.')}</span>`;
 for(const id of ['speak','downloadReport','downloadAudio','saveAttempt'])$(id).disabled=!r;
 $('modeBadge').textContent=state.demo?'SYNTHETIC MIDI EXAMPLE':'YOUR RECORDINGS · LOCAL';$('sessionCount').textContent=getHistory().length;
}
function emptyResult(){return {version:VERSION,findings:[],score:null,dimensions:{notes:null,rhythm:null,tone:null,technique:null},alignment:[],referenceCount:0,learnerCount:0,limitations:['Manual comparison mode. Observations are instructor supplied, not automatically detected.','Pressure, exact contact, object orientation and pronunciation are not automatically assessed.'],rubric:{timingTolerance:Number($('tolerance').value),allowSlower:$('allowSlower').checked}};}
function assess(){if(!state.reference||!state.learner){toast('Add both an expert reference and a learner attempt.');return;}stop();const a=state.reference,b=state.learner;if($('domain').value!=='music'){state.result=emptyResult();render();return;}
 if(a.warnings?.length||b.warnings?.length||!a.events?.length||!b.events?.length){state.result=emptyResult();state.result.limitations=[...(a.warnings||[]).map(w=>'Expert: '+w),...(b.warnings||[]).map(w=>'Learner: '+w),'Unable to assess reliably. Review the recordings manually or upload clean single-note audio or MIDI.'];render();toast('Assessment withheld: recording evidence is insufficient.');return;}
 try{state.result=compare(a.events,b.events,{timingTolerance:Number($('tolerance').value),allowSlower:$('allowSlower').checked,precise:a.precise&&b.precise});render();}catch(e){toast(e.message);}}
function setDemo(kind){if(busy)return;stop();state.demo=true;$('domain').value='music';$('domainNotice').classList.add('hidden');const d=demoEvents(kind);for(const s of ['reference','learner']){cleanSide(s);state[s]={events:d[s],name:s==='reference'?'Reference phrase':'Practice phrase',sourceLabel:'synthesized example',duration:Math.max(...d[s].map(e=>e.end)),precise:true};updateSide(s);}if(kind==='ambiguous')state.learner.warnings=['This example simulates a recording with insufficient reliable evidence. No diagnosis is produced.'];document.querySelectorAll('[data-demo]').forEach(b=>b.classList.toggle('active',b.dataset.demo===kind));assess();}
function newSession(){if(busy)return;stop();if(recorder?.state==='recording')recorder.stop();for(const s of ['reference','learner']){cleanSide(s);state[s]=null;updateSide(s);}state.demo=false;state.result=null;$('sessionTitle').value='Untitled practice';document.querySelectorAll('[data-demo]').forEach(b=>b.classList.remove('active'));render();toast('Ready for a new practice. Add your expert reference first.');}
function analyzeInWorker(samples,sampleRate){return new Promise((resolve,reject)=>{const w=new Worker('audio-worker.js',{type:'module'});const t=setTimeout(()=>{w.terminate();reject(Error('Audio analysis took too long. Try a shorter phrase or MIDI.'));},90000);w.onmessage=e=>{clearTimeout(t);w.terminate();e.data.error?reject(Error(e.data.error)):resolve(e.data);};w.onerror=e=>{clearTimeout(t);w.terminate();reject(Error(e.message));};w.postMessage({samples,sampleRate},[samples.buffer]);});}
async function loadFile(s,file){if(!file||busy)return;if(file.size>250*1024*1024){toast('Please use a file smaller than 250 MB.');return;}busy=true;stop();$('analyze').disabled=true;$('analyze').textContent='Reading recording…';try{if(state.demo){for(const side of ['reference','learner']){cleanSide(side);state[side]=null;updateSide(side);}state.demo=false;}state.result=null;cleanSide(s);state[s]=null;render();const buffer=await file.arrayBuffer();const ext=file.name.split('.').pop().toLowerCase();let item={name:file.name,sourceLabel:'recording',duration:0,precise:false,events:[],warnings:[]};
 if(['mid','midi'].includes(ext)){item.events=parseMidi(buffer);item.precise=true;item.sourceLabel='direct MIDI';item.duration=Math.max(...item.events.map(e=>e.end));}
 else if(ext==='json'){const data=JSON.parse(new TextDecoder().decode(buffer));item.events=validateEvents(Array.isArray(data)?data:data.events);item.sourceLabel='imported event estimates';item.duration=Math.max(...item.events.map(e=>e.end));}
 else {const isVideo=file.type.startsWith('video/')||['mp4','mov','webm','m4v'].includes(ext);item.url=URL.createObjectURL(file);item.mediaType=isVideo?'video':'audio';const v=$(s+'Video');v.src=item.url;await new Promise((resolve,reject)=>{const timeout=setTimeout(()=>reject(Error('Media could not be opened. Try MP4 H.264/AAC or WAV audio.')),12000);v.onloadedmetadata=()=>{clearTimeout(timeout);resolve();};v.onerror=()=>{clearTimeout(timeout);reject(Error('This browser cannot play this recording. Try MP4 or WAV.'));};});item.duration=v.duration;if(!Number.isFinite(item.duration)||item.duration>60){URL.revokeObjectURL(item.url);throw Error('Use a short recording up to 60 seconds for this release.');}if(isVideo)v.classList.remove('hidden');
 if($('domain').value==='music'){try{const decoded=await audio().decodeAudioData(buffer.slice(0));const offline=new OfflineAudioContext(1,Math.ceil(decoded.duration*12000),12000),source=offline.createBufferSource();source.buffer=decoded;source.connect(offline.destination);source.start();const mono=await offline.startRendering();$('analyze').textContent='Measuring audio locally…';const features=await analyzeInWorker(mono.getChannelData(0).slice(),12000);item.events=features.events;item.warnings=features.warnings;item.sourceLabel='experimental audio estimates';}catch{item.warnings=['Audio could not be decoded or measured. Add a matching WAV or MIDI file, or use manual review.'];item.sourceLabel='manual review';}}else item.sourceLabel='manual observation';}
 state[s]=item;updateSide(s);toast(`${s==='reference'?'Expert':'Learner'} recording ready.`);
 }catch(e){state[s]=null;cleanSide(s);updateSide(s);toast(e.message);}finally{busy=false;$('analyze').disabled=false;$('analyze').innerHTML='Compare performances <span>↗</span>';render();}}
function synth(events,from,to,speed){const ac=audio();for(const e of events){if(e.start<from-.01||e.start>to)continue;const osc=ac.createOscillator(),gain=ac.createGain();osc.type='triangle';osc.frequency.value=440*2**((e.pitch-69)/12);const at=ac.currentTime+(e.start-from)/speed+.03,d=Math.max(.03,(Math.min(e.end,to)-e.start)/speed);gain.gain.setValueAtTime(0,at);gain.gain.linearRampToValueAtTime(.10,at+.01);gain.gain.exponentialRampToValueAtTime(.0001,at+d);osc.connect(gain);gain.connect(ac.destination);osc.start(at);osc.stop(at+d+.02);sources.push(osc);}}
async function play(finding=null){if(playing&&!finding){stop();return;}if(!state.reference||!state.learner){toast('Add both recordings first.');return;}stop();const heard=$('listenTo').value,speed=Number($('speed').value);await audio().resume();let maxDuration=0;for(const s of ['reference','learner']){const x=state[s],span=finding?.[s];let start=span?Math.max(0,span[0]-.3):0,end=span?Math.min(x.duration,span[1]+.6):x.duration;if(finding&&!span){continue;}maxDuration=Math.max(maxDuration,(end-start)/speed);const v=$(s+'Video');if(x.url){v.currentTime=start;v.playbackRate=speed;v.muted=s!==heard;try{await v.play();}catch{toast('Playback was blocked. Use the recording’s play control.');}}else if(s===heard)synth(x.events||[],start,end,speed);}
 playing=true;$('playBoth').textContent='Ⅱ';stopTimer=setTimeout(stop,maxDuration*1000+100);if(finding){selectedId=finding.id;render();document.querySelector(`[data-finding="${finding.id}"]`)?.scrollIntoView({block:'nearest',behavior:'smooth'});}}
async function record(s,button){if(busy){toast('Wait for the current recording to finish loading.');return;}if(recorder?.state==='recording'){recorder.stop();return;}try{mediaStream=await navigator.mediaDevices.getUserMedia({video:true,audio:true});recordingSide=s;const chunks=[];recorder=new MediaRecorder(mediaStream);recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data);};recorder.onstop=()=>{clearTimeout(record.timer);mediaStream.getTracks().forEach(t=>t.stop());button.textContent='● Record';const type=recorder.mimeType;const ext=type.includes('mp4')?'mp4':'webm';loadFile(recordingSide,new File(chunks,`recorded-${recordingSide}.${ext}`,{type}));};recorder.start();button.textContent='■ Stop recording';toast('Recording camera and microphone. Press Stop when finished (maximum 60 seconds).');record.timer=setTimeout(()=>{if(recorder.state==='recording')recorder.stop();},59000);}catch(e){toast('Camera or microphone unavailable. Allow access, or upload a recording instead.');}}
function speechText(){const r=state.result;if(!r)return '';const f=r.findings.filter(x=>x.review!=='dismissed');return `MIMORA. ${$('sessionTitle').value}. ${state.demo?'This is a synthetic demonstration. ':''}${r.score===null?'A score is withheld because this evidence needs review. ':`Your assessed score is ${r.score} out of 100, for notes and eligible rhythm only. `}${f.length?f.map((x,i)=>`Moment ${i+1}. ${x.status==='possible'?'Possible difference. ':''}${x.observation} ${x.action}`).join(' '):'No significant differences were detected in the dimensions assessed. '}${r.limitations.join(' ')}`;}
$('speak').onclick=()=>{if(!('speechSynthesis'in window)){toast('Spoken playback is unavailable in this browser. Use the local server’s WAV export.');return;}if(speechSynthesis.speaking){speechSynthesis.cancel();$('speak').textContent='▶ Listen to feedback';return;}const u=new SpeechSynthesisUtterance(speechText());u.rate=.93;u.onend=u.onerror=()=>{$('speak').textContent='▶ Listen to feedback';};speechSynthesis.speak(u);$('speak').textContent='■ Stop feedback';};
$('downloadReport').onclick=()=>{if(state.result)download(`${state.demo?'SYNTHETIC EXAMPLE — NOT A REAL PERFORMANCE ASSESSMENT\n\n':''}${reportText(state.result,$('sessionTitle').value)}`,'mimora-feedback.txt');};
$('downloadAudio').onclick=async()=>{const button=$('downloadAudio');button.disabled=true;try{const res=await fetch('/api/speech',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({text:speechText()})});if(!res.ok||!(res.headers.get('content-type')||'').includes('audio/'))throw Error('WAV export requires the included local server. Online, use “Listen to feedback” for spoken audio.');download(await res.arrayBuffer(),'mimora-feedback.wav','audio/wav');}catch(e){toast(e.message);}finally{button.disabled=false;}};
$('saveAttempt').onclick=()=>{if(!state.result)return;const h=getHistory();h.unshift({id:crypto.randomUUID(),title:$('sessionTitle').value,date:new Date().toISOString(),demo:state.demo,domain:$('domain').value,result:structuredClone(state.result),reference:{events:state.reference.events,sourceLabel:state.reference.sourceLabel,duration:state.reference.duration,name:state.reference.name,precise:state.reference.precise},learner:{events:state.learner.events,sourceLabel:state.learner.sourceLabel,duration:state.learner.duration,name:state.learner.name,precise:state.learner.precise}});persistHistory(h);toast('Attempt saved on this device. Recordings themselves are not retained.');};
function historyView(){const h=getHistory();$('historyList').innerHTML=h.length?h.map((x,index)=>{const previous=h.slice(index+1).find(p=>p.title===x.title&&p.domain===x.domain&&p.demo===x.demo&&JSON.stringify(p.reference.events)===JSON.stringify(x.reference.events)&&JSON.stringify(p.result.rubric)===JSON.stringify(x.result.rubric));const delta=previous&&x.result.score!==null&&previous.result.score!==null?x.result.score-previous.result.score:null;return `<article class="history-card"><div><h3>${esc(x.title)}</h3><p>${new Date(x.date).toLocaleString()} · ${x.demo?'Synthetic demo':esc(x.domain)} · ${x.result.findings.filter(f=>f.review!=='dismissed').length} observations${delta!==null?` · ${delta>=0?'+':''}${delta} points vs prior saved attempt`:''}</p></div><strong>${x.result.score??'—'}</strong><button class="button small" data-open="${x.id}">Open report</button><button class="button small text" data-delete="${x.id}">Delete</button></article>`;}).join(''):'<div class="empty"><h3>A fresh beginning.</h3><p>Save your first attempt from the practice studio.</p></div>';}
function view(id){document.querySelectorAll('.view').forEach(v=>v.classList.toggle('hidden',v.id!==id));document.querySelectorAll('.nav').forEach(b=>b.classList.toggle('active',b.dataset.view===id));$('breadcrumb').textContent=({studio:'Practice studio',library:'My sessions',guide:'How it works'})[id];if(id==='library')historyView();window.scrollTo(0,0);}
function applyDomain(){const d=$('domain').value;$('domainNotice').classList.toggle('hidden',d==='music');$('domainNotice').textContent=d==='craft'?'Craft practice uses side-by-side recordings and timestamped instructor observations. Movement errors, pressure and object orientation are not automatically detected.':'Language practice uses side-by-side listening and timestamped instructor observations. Automatic pronunciation assessment is not available in this release.';state.result=null;render();}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.view)view(b.dataset.view);if(b.dataset.demo)setDemo(b.dataset.demo);if(b.dataset.record)record(b.dataset.record,b);if(b.dataset.replay)play(state.result.findings.find(f=>f.id===b.dataset.replay));if(b.dataset.review){const f=state.result.findings.find(f=>f.id===b.dataset.id);f.review=b.dataset.review==='accept'?'accepted':'dismissed';if(f.review==='dismissed'){state.result.score=null;state.result.dimensions.notes=null;state.result.dimensions.rhythm=null;state.result.limitations.push('Score withheld after instructor dismissal. Resolve source events and compare again to recompute.');}render();}if(b.id==='addObservation')$('noteDialog').showModal();if(b.dataset.open){const x=getHistory().find(x=>x.id===b.dataset.open);stop();for(const s of ['reference','learner']){cleanSide(s);state[s]=x[s];updateSide(s);}state.demo=x.demo;state.result=x.result;$('sessionTitle').value=x.title;$('domain').value=x.domain;view('studio');render();toast('Saved report opened. Reattach original recordings for recorded playback; note events can be synthesized.');}if(b.dataset.delete){persistHistory(getHistory().filter(x=>x.id!==b.dataset.delete));historyView();}});
$('newSession').onclick=newSession;$('analyze').onclick=assess;$('playBoth').onclick=()=>play();$('speed').onchange=stop;$('listenTo').onchange=stop;$('domain').onchange=applyDomain;$('rubricButton').onclick=()=>$('rubricDialog').showModal();$('rubricDialog').addEventListener('close',()=>{state.result=null;render();toast('Settings updated. Compare again to apply them.');});for(const s of ['reference','learner'])$(s+'File').onchange=e=>loadFile(s,e.target.files[0]);
$('closeNote').onclick=()=>$('noteDialog').close();$('noteForm').onsubmit=e=>{e.preventDefault();const a=Number($('noteReference').value),b=Number($('noteLearner').value);if(a>state.reference.duration||b>state.learner.duration){toast('Observation timestamps must be inside each recording.');return;}state.result.findings.push({id:crypto.randomUUID(),category:'Observation',status:'unverified',reference:[a,Math.min(a+1,state.reference.duration)],learner:[b,Math.min(b+1,state.learner.duration)],observation:$('noteObservation').value,action:$('noteAction').value,evidence:'Instructor-supplied observation; original recordings',method:'human-review-1.0',review:'accepted',scoringEligible:false});$('noteDialog').close();$('noteForm').reset();render();};
$('clearHistory').onclick=()=>{if(confirm('Delete all saved practice reports from this browser?')){persistHistory([]);historyView();}};
$('inspectHands').onclick=async()=>{const status=$('visionStatus');if(!['reference','learner'].some(s=>state[s]?.mediaType==='video')){status.textContent='Add a video recording in the studio first, then pause at the moment you want to inspect.';return;}status.textContent='Loading the optional hand model. Processing stays in this browser…';try{if(!vision){const {FilesetResolver,HandLandmarker}=await import('https://cdn.jsdelivr.net/npm/@mediapipe/tasks-vision@0.10.21/vision_bundle.mjs');vision=await HandLandmarker.createFromOptions(await FilesetResolver.forVisionTasks('https://cdn.jsdelivr.net/npm/@mediapipe/tasks-vision@0.10.21/wasm'),{baseOptions:{modelAssetPath:'https://storage.googleapis.com/mediapipe-models/hand_landmarker/hand_landmarker/float16/1/hand_landmarker.task'},runningMode:'IMAGE',numHands:2});}let count=0;for(const s of ['reference','learner']){const v=$(s+'Video');if(state[s]?.mediaType!=='video'||v.readyState<2)continue;v.pause();const r=vision.detect(v),c=$(s+'Canvas'),ctx=c.getContext('2d');c.width=c.clientWidth*2;c.height=c.clientHeight*2;ctx.clearRect(0,0,c.width,c.height);const scale=Math.min(c.width/v.videoWidth,c.height/v.videoHeight),w=v.videoWidth*scale,h=v.videoHeight*scale,dx=(c.width-w)/2,dy=(c.height-h)/2;for(const hand of r.landmarks){count++;for(const point of hand){ctx.beginPath();ctx.arc(dx+point.x*w,dy+point.y*h,4,0,Math.PI*2);ctx.fillStyle='#c3eaa4';ctx.fill();}}}status.textContent=`${count} hands located in paused frames. Landmarks are a visual aid only; they do not establish correct fingering or contact.`;view('studio');toast(status.textContent);}catch(e){status.textContent='Hand inspection could not load. Check your connection and browser WebAssembly support. No technique judgment has been made.';}};
document.querySelectorAll('label[role=button]').forEach(label=>label.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();label.querySelector('input').click();}}));
window.addEventListener('beforeunload',()=>{stop();mediaStream?.getTracks().forEach(t=>t.stop());});setDemo('difference');
